KMP #include&lt;bits/stdc++.h&gt; using namespace std; const int N=100010; int ne[N]; int main(){ int len1,len2; string s1,s2; cin&gt;&gt;len1&gt;&gt;s1&gt;&gt;len2&gt;&gt;s2; s1=&#39; &#39;+s1; s2=&#39; &#39;+s2; for(int i=2,j=0;i&lt;=len1;i++){ while(j&amp;&amp;s1[j+1]!=s1[i])j=ne[j]; if(s1[j+1]==s1[i])j++; ne[i]=j; } for(int i=1,j=0;i&lt;=len2;i++){ while(j&amp;&amp;s1[j+1]!=s2[i])j=ne[j]; if(s1[j+1]==s2[i])j++; if(j==len1){ cout&lt;&lt;i-len1&lt;&lt;&#39; &#39;; } } return 0; } Trie - 字符串统计 维护一个字符串集合，支持两种操作：
I x 向集合中插入一个字符串 $x$； Q x 询问一个字符串在集合中出现了多少次。 共有 $N$ 个操作，所有输入的字符串总长度不超过 $10^5$，字符串仅包含小写英文字母。 #include&lt;bits/stdc++.h&gt; using namespace std; const int N=100010; int a[N][26],cnt[N],idx; void fi(char str[]){ int m=0; for(int i=0;str[i];i++){ int t=str[i]-&#39;a&#39;; if(!a[m][t]){ a[m][t]=++idx; } m=a[m][t]; } cnt[m]++; } void fq(char str[]){ int m=0; for(int i=0;str[i];i++){ int t=str[i]-&#39;a&#39;; if(!a[m][t]){ printf(&#34;0\n&#34;); return; } m=a[m][t]; } printf(&#34;%d\n&#34;,cnt[m]); } int main(){ int n; char c,str[N]; cin&gt;&gt;n; while(n--){ cin&gt;&gt;c&gt;&gt;str; if(c==&#39;I&#39;)fi(str); else fq(str); } return 0; } 并查集 #include&lt;iostream&gt; using namespace std; const int N=100010; int p[N];//定义多个集合 int find(int x) { if(p[x]!=x) p[x]=find(p[x]); return p[x]; } int main() { int n,m; scanf(&#34;%d%d&#34;,&amp;n,&amp;m); for(int i=1;i&lt;=n;i++) p[i]=i; while(m--) { char op[2]; int a,b; scanf(&#34;%s%d%d&#34;,op,&amp;a,&amp;b); if(*op==&#39;M&#39;) p[find(a)]=find(b);//集合合并操作 else if(find(a)==find(b)) //如果祖宗节点一样,就输出yes printf(&#34;Yes\n&#34;); else printf(&#34;No\n&#34;); } return 0; } 模拟散列表 #include&lt;bits/stdc++.h&gt; using namespace std; const int N=100003; int h[N],e[N],ne[N],idx,f; int main(){ int n,x; cin&gt;&gt;n; string s; memset(h,-1,sizeof(h)); while(n--){ cin&gt;&gt;s&gt;&gt;x; int k=(x%N+N)%N; if(s==&#34;I&#34;){ e[idx]=x; ne[idx]=h[k]; h[k]=idx; idx++; continue; } k=h[k]; f=1; while(k!=-1){ if(e[k]==x){ printf(&#34;Yes\n&#34;); f=0; break; } k=ne[k]; } if(f)printf(&#34;No\n&#34;); } return 0; } 字符串哈希 给定一个长度为 $n$ 的字符串，再给定 $m$ 个询问，每个询问包含四个整数 $l_1, r_1, l_2, r_2$，请你判断 $[l_1, r_1]$ 和 $[l_2, r_2]$ 这两个区间所包含的字符串子串是否完全相同。
字符串中只包含大小写英文字母和数字。
#include&lt;bits/stdc++.h&gt; using namespace std; typedef unsigned long long ULL; const int N=100010,P=131; ULL h[N],p[N]; ULL f(int l,int r){ return h[r]-h[l-1]*p[r-l+1]; } int main(){ char s[N]; int n,m,l1,r1,l2,r2; scanf(&#34;%d%d%s&#34;,&amp;n,&amp;m,s+1); p[0]=1; for(int i=1;i&lt;=n;i++){ p[i]=131*p[i-1]; h[i]=h[i-1]*P+s[i]; } while(m--){ scanf(&#34;%d%d%d%d&#34;,&amp;l1,&amp;r1,&amp;l2,&amp;r2); if(f(l1,r1)==f(l2,r2))printf(&#34;Yes\n&#34;); else printf(&#34;No\n&#34;); } return 0; } 树状数组 给定长度为 $N$ 的数列 $A$，然后输入 $M$ 行操作指令。
第一类指令形如 C l r d，表示把数列中第 $l \sim r$ 个数都加 $d$。
第二类指令形如 Q x，表示询问数列中第 $x$ 个数的值。
对于每个询问，输出一个整数表示答案。
树状数组主要解决的是: 单点修改：a[k] 加上一个数。 区间求值： a[l~r]内所有元素和。 本题加上差分即可
#include &lt;bits/stdc++.h&gt; using namespace std; const int N = 100009; int n, m, a[N], t[N]; int low_bit(int x) { return x &amp; -x; } void add(int x,int y) { for(;x &lt;= n;x += low_bit(x)) t[x] += y; return; } int ask(int x) { int ans = a[x]; for(;x;x -= low_bit(x)) ans += t[x]; return ans; } int main() { cin &gt;&gt; n &gt;&gt; m; for(int i = 1;i &lt;= n;++ i) cin &gt;&gt; a[i]; char ch; for(int i = 1, l, r, d;i &lt;= m;++ i) { cin &gt;&gt; ch; if (ch == &#39;C&#39;) { cin &gt;&gt; l &gt;&gt; r &gt;&gt; d; add(l, d); add(r + 1, -d); } if (ch == &#39;Q&#39;) { cin &gt;&gt; d; cout &lt;&lt; ask(d) &lt;&lt; endl; } } return 0; }

