复杂度O(n) nth_element(a+1,a+k,a+n+1)//默认的升序 nth_element(a+1,a+k,a+n+1,cmp)//自定义比较方式 //cout&lt;&lt;a[k]即可 //nth_element 并没有对数组全部排序 仅仅只是找到了第k小的数并将其放到第k个位置上。 //k之前的都比k小，k之后的都比k大，但是并不是有序排列 bitset bitset&lt;8&gt; b2(12); //二进制长度8，将12转化为二进制存到其中。 cout &lt;&lt; b2 &lt;&lt; endl; string s = &#34;10010&#34;; bitset&lt;8&gt; b3(s); cout &lt;&lt; b3 &lt;&lt; endl;//存字符串/字符数组 bitset&lt;8&gt; bs(13); cout &lt;&lt; bs &lt;&lt;endl; //00001101 for(int i=0;i&lt;7;i++) cout&lt;&lt;bs[i]; //10110000 //像数字一样的操作 b2 |= b3; b2 &amp;= b3; b2 ^= b3; b2 = ~b2; b2 &lt;&lt;= 2; //自带函数 int cnt_1 = b2.count(); //查询二进制数组中，1的个数； int len = b2.size(); //二进制数组的长度，就是定义的长度； int test = b2.test(7); //判断第x个位置是0还是1，也就是输出第x个位置，注意逆序； b2.flip(); //将二进制每一位取反； b2.flip(3); //将二进制第x位取反； b2.set(); //将二进制每一位置为1； reset置为0； b2.set(3); //将第x个位置置为1； string ss = b2.to_string(); //将二进制数组转化为字符串。 其他 去重 memcpy(backup, g, sizeof g);//数组拷贝 int n = unique(a,a+6)-a;//将重复的数字放在了最后面 矩阵与一个整数的映射 123 456 789
//当a=N*(i-1)+y时，即xy都是1~n void get(int a, int &amp;x,int &amp;y){ y=a%n; if(y==0)y=n; x=(a-y)/n+1; }
